/**
 * Unit 3 (composite/implicit/inverse differentiation) and Unit 4 (contextual
 * applications of differentiation) template families.
 *
 * Every family below is an original construction: numbers, functions, and
 * contexts are generated by the RNG, and no College Board wording is reused.
 */

import {
  dec,
  frac,
  pick,
  ri,
  term,
  type QuestionTemplate,
  type RNG,
} from "../question-templates";
import { fitWindow, sampleCurve } from "../figures";

const U3 = "unit-3-differentiation-composite-implicit-inverse";
const U4 = "unit-4-contextual-applications-of-differentiation";

/** Drop a coefficient of 1 (and render -1 as a bare minus) before a body. */
const coefTerm = (c: number, body: string): string => {
  if (c === 1) return body;
  if (c === -1) return `-${body}`;
  return `${c}${body}`;
};

const signedLinear = (m: number, b: number): string => {
  const head = coefTerm(m, "x");
  return `${head}${term(b, "")}`;
};

